/**
 * Represents one row from the Google cluster trace {@code task_events} tables.
 * The schema (13 columns) is:
 *   time, missing_info, job_id, task_index, machine_id, event_type,
 *   user, scheduling_class, priority, cpu_request, memory_request,
 *   disk_space_request, different_machines_restriction.
 * Timestamps are in microseconds since the start of the trace.
 */
public class TaskEvent {

    // Event type constants (as defined by the Google cluster trace schema).
    public static final int SUBMIT = 0;
    public static final int SCHEDULE = 1;
    public static final int EVICT = 2;
    public static final int FAIL = 3;
    public static final int FINISH = 4;
    public static final int KILL = 5;
    public static final int LOST = 6;
    public static final int UPDATE_PENDING = 7;
    public static final int UPDATE_RUNNING = 8;

    public long time;
    public int missingInfo;
    public long jobId;
    public int taskIndex;
    public long machineId;
    public int eventType;
    public String userName;
    public int schedulingClass;
    public int priority;
    public double cpuRequest;
    public double memoryRequest;
    public double diskSpaceRequest;
    public int differentMachinesRestriction;

    public TaskEvent() {}

    public static TaskEvent fromCsv(String line) {
        if (line == null || line.isEmpty()) return null;
        String[] f = line.split(",", -1);
        if (f.length < 6) return null;
        try {
            TaskEvent e = new TaskEvent();
            e.time = parseLong(f[0], 0L);
            e.missingInfo = parseInt(f[1], 0);
            e.jobId = parseLong(f[2], 0L);
            e.taskIndex = parseInt(f[3], 0);
            e.machineId = parseLong(f[4], 0L);
            e.eventType = parseInt(f[5], -1);
            e.userName = f.length > 6 ? f[6] : "";
            e.schedulingClass = f.length > 7 ? parseInt(f[7], 0) : 0;
            e.priority = f.length > 8 ? parseInt(f[8], 0) : 0;
            e.cpuRequest = f.length > 9 ? parseDouble(f[9], 0.0) : 0.0;
            e.memoryRequest = f.length > 10 ? parseDouble(f[10], 0.0) : 0.0;
            e.diskSpaceRequest = f.length > 11 ? parseDouble(f[11], 0.0) : 0.0;
            e.differentMachinesRestriction = f.length > 12 ? parseInt(f[12], 0) : 0;
            return e;
        } catch (NumberFormatException ex) {
            return null;
        }
    }

    private static long parseLong(String s, long dflt) {
        return (s == null || s.isEmpty()) ? dflt : Long.parseLong(s);
    }

    private static int parseInt(String s, int dflt) {
        return (s == null || s.isEmpty()) ? dflt : Integer.parseInt(s);
    }

    private static double parseDouble(String s, double dflt) {
        return (s == null || s.isEmpty()) ? dflt : Double.parseDouble(s);
    }

    @Override
    public String toString() {
        return "TaskEvent{time=" + time + ", jobId=" + jobId
                + ", taskIndex=" + taskIndex + ", eventType=" + eventType + "}";
    }
}
