import java.util.zip.GZIPInputStream;

/**
 * For every job that reaches a {@code FINISH} event, emits a tuple
 * {@code (jobId, maxTasksInStage)} where a stage is a run of task
 * {@code SUBMIT} events separated from the next SUBMIT for the same job
 * by less than {@code sesssize} seconds.
 */
public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  " + taskInput);
        System.out.println("job_input  " + jobInput);
        final int sesssize = params.getInt("sesssize", 600);
        final long sessionGapMillis = sesssize * 1000L;

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);

        SourceFunction<TaskEvent> taskSource =
                AppBase.taskSourceOrTest(new GzipTaskEventSource(taskInput));
        SourceFunction<JobEvent> jobSource =
                AppBase.jobSourceOrTest(new GzipJobEventSource(jobInput));

        DataStream<TaskEvent> taskSubmits = env
                .addSource(taskSource)
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<TaskEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((event, ts) -> event.time / 1000L))
                .filter((FilterFunction<TaskEvent>) t -> t.eventType == TaskEvent.SUBMIT);

        DataStream<JobEvent> jobFinishes = env
                .addSource(jobSource)
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<JobEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((event, ts) -> event.time / 1000L))
                .filter((FilterFunction<JobEvent>) j -> j.eventType == JobEvent.FINISH);

        DataStream<Tuple2<Long, Long>> result = taskSubmits
                .keyBy((KeySelector<TaskEvent, Long>) t -> t.jobId)
                .connect(jobFinishes.keyBy((KeySelector<JobEvent, Long>) j -> j.jobId))
                .process(new LongestStageProcessor(sessionGapMillis))
                .returns(TypeInformation.of(new TypeHint<Tuple2<Long, Long>>() {}));

        SinkFunction<Tuple2<Long, Long>> defaultSink = new FileOutputSink(outputPath);
        @SuppressWarnings({"rawtypes", "unchecked"})
        SinkFunction<Tuple2<Long, Long>> chosenSink =
                (SinkFunction) AppBase.sinkOrTest(defaultSink);
        DataStreamSink<Tuple2<Long, Long>> sinkOp = result.addSink(chosenSink);
        sinkOp.setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

    // ---------------------------------------------------------------------
    //  Core processing: longest-stage computation
